<script setup lang="ts">import{ref,watch}from'vue';import CrudForm from './crud/CrudForm.vue';const props=defineProps<{modelValue:boolean;role:any}>();const emit=defineEmits<{(e:'update:modelValue',v:boolean):void;(e:'save',v:any):void}>();const model=ref({roleName:''});watch(()=>props.role,r=>{model.value={roleName:r?.roleName||''}},{immediate:true});const fields=[{code:'roleName',label:'角色名称',type:'text',required:true,editable:true}];function submit(){emit('save',{roleName:model.value.roleName.trim()})}</script><template><CrudForm :model-value="modelValue" title="编辑角色" :fields="fields" :model="model" @update:model-value="emit('update:modelValue',$event)" @update:model="model=$event" @submit="submit"/></template>
